---@alias gcp.datastore_v1.QueryResultBatchMoreResultsEnum "MORE_RESULTS_TYPE_UNSPECIFIED"|"NOT_FINISHED"|"MORE_RESULTS_AFTER_LIMIT"|"MORE_RESULTS_AFTER_CURSOR"|"NO_MORE_RESULTS"

